const enemies=[],keys={},tracers=[],joyVec={x:0,y:0};const hitEl=document.querySelector('#hitmarker'),toastEl=document.querySelector('#toast');
function announce(text,seconds=1.6){toastEl.textContent=text;toastEl.classList.add('show');toastTimer=seconds;}
function updateHUD(){document.querySelector('#healthNum').textContent=Math.ceil(player.health);document.querySelector('#healthBar').style.width=`${Math.max(0,player.health)}%`;document.querySelector('#staminaBar').style.width=`${player.stamina}%`;document.querySelector('#ammoNum').textContent=String(player.ammo).padStart(2,'0');document.querySelector('#waveNum').textContent=String(wave).padStart(2,'0');}
function makeEnemy(x,z,kind=0){const g=new THREE.Group();g.position.set(x,0,z);g.userData.enemy=true;g.userData.hp=kind===2?3:2;g.userData.cooldown=1.2+Math.random()*1.8;g.userData.speed=.75+Math.random()*.25;g.userData.kind=kind;const coat=kind===0?red:(kind===1?blue:mat(0x46443d)),skin=mat(0xb18868),metal=kind===2?gold:iron;
 cylinder(g,0,1.02,0,.32,.4,.92,coat,8);sphere(g,0,1.67,0,.24,skin);cylinder(g,0,1.91,0,.28,.21,.23,metal,8);box(g,0,2.045,0,.38,.07,.35,metal);
 for(const side of [-1,1]){const arm=cylinder(g,side*.4,1.14,0,.11,.14,.62,coat,7);arm.rotation.z=side*-.38;const leg=cylinder(g,side*.16,.42,0,.13,.16,.68,leather,7);leg.userData.leg=true;}
 box(g,.18,1.2,.34,.09,.09,.78,wood,.05);box(g,.18,1.2,.72,.055,.055,.48,iron,.05);sphere(g,.1,1.23,.4,.09,skin);if(kind===1)box(g,-.01,1.04,-.02,.58,.11,.04,gold,0,0,.3);if(kind===2)box(g,0,1.12,-.22,.56,.58,.12,darkStone);scene.add(g);enemies.push(g);return g;}
function spawnWave(){killsThisWave=0;const n=waveCount+Math.min(wave-1,4);for(let i=0;i<n;i++){const lane=(i%5)-2,row=Math.floor(i/5),x=lane*2.7+(Math.random()-.5)*1.4,z=-20-row*2.6-Math.random()*2;makeEnemy(x,z,i%4===3?1:0);}announce(wave===1?'THEY’RE THROUGH THE GATE':`WAVE ${String(wave).padStart(2,'0')} · INCOMING`,2.5);}
function killEnemy(e){const idx=enemies.indexOf(e);if(idx<0)return;enemies.splice(idx,1);scene.remove(e);player.score++;killsThisWave++;announce(['GOOD SHOT','DOWN','KEEP THE LINE'][Math.floor(Math.random()*3)],.7);if(killsThisWave>=waveCount+Math.min(wave-1,4)&&enemies.length===0){if(wave>=5){won=true;endGame(true);}else{wave++;spawnTimer=4;announce('GATE HELD · NEXT WAVE INCOMING',3);}}}
function makeTracer(end){const start=camera.getWorldPosition(new THREE.Vector3()).add(camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(.7));const geo=new THREE.BufferGeometry().setFromPoints([start,end]);const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color:0xffdd97,transparent:true,opacity:.8}));scene.add(line);tracers.push({line,life:.07});}
function shoot(){if(!started||!player.alive||reloading||shotCooldown>0)return;if(player.ammo<=0){announce('EMPTY · PRESS R TO RELOAD',1.1);return;}player.ammo--;shotCooldown=.42;weapon.position.z=-.64;weapon.rotation.x=-.19;const flash=new THREE.PointLight(0xffbd6a,5,4);flash.position.set(.35,-.2,-1.05);camera.add(flash);setTimeout(()=>camera.remove(flash),65);raycaster.setFromCamera(new THREE.Vector2(0,0),camera);const meshes=[];for(const e of enemies)meshes.push(...e.children);const hits=raycaster.intersectObjects(meshes,true);makeTracer(hits.length?hits[0].point:camera.position.clone().add(camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(40)));if(hits.length){let e=hits[0].object;while(e&&!e.userData.enemy)e=e.parent;if(e){e.userData.hp--;hitEl.classList.add('show');setTimeout(()=>hitEl.classList.remove('show'),100);if(e.userData.hp<=0)killEnemy(e);}}updateHUD();}
function reload(){if(!started||reloading||player.ammo===6)return;reloading=true;announce('RELOADING…',1.4);setTimeout(()=>{if(player.alive){player.ammo=6;updateHUD();announce('LOCK & LOAD',.8);}reloading=false;},1450);}
function damage(amount){if(!player.alive)return;player.health=Math.max(0,player.health-amount);const d=document.querySelector('#damage');d.classList.add('show');setTimeout(()=>d.classList.remove('show'),180);updateHUD();if(player.health<=0)endGame(false);}
