document.querySelector('#fireBtn').addEventListener('touchstart',e=>{e.preventDefault();shoot();},{passive:false});document.querySelector('#fireBtn').addEventListener('click',shoot);
const joy=document.querySelector('#joy'),stick=document.querySelector('#stick');function setJoy(e){const r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),max=39,f=Math.min(1,max/(d||1));joyVec.x=dx*f/max;joyVec.y=dy*f/max;stick.style.transform=`translate(${joyVec.x*max}px,${joyVec.y*max}px)`;}
joy.addEventListener('pointerdown',e=>{joy.setPointerCapture(e.pointerId);setJoy(e)});joy.addEventListener('pointermove',e=>{if(e.buttons)setJoy(e)});function resetJoy(){joyVec.x=0;joyVec.y=0;stick.style.transform='';}joy.addEventListener('pointerup',resetJoy);joy.addEventListener('pointercancel',resetJoy);

